import { Injectable, Logger, ServiceUnavailableException } from '@nestjs/common';
import { createHash, createHmac, randomUUID } from 'node:crypto';

/**
 * Minimal S3 SigV4 presigning for the single Cloudflare R2 bucket.
 * No arbitrary URL or caller-provided storage key can reach this class.
 * Keys are generated by SellerListingAssetService under an owner-scoped prefix.
 */
@Injectable()
export class SellerR2StorageService {
  private readonly logger = new Logger(SellerR2StorageService.name);
  private settings() {
    const account = process.env.CLOUDFLARE_ACCOUNT_ID?.trim();
    const accessKey = process.env.CLOUDFLARE_ACCESS_KEY_ID?.trim();
    const secret = process.env.CLOUDFLARE_SECRET_ACCESS_KEY?.trim();
    const bucket = process.env.CLOUDFLARE_R2_BUCKET_NAME?.trim();
    if (!account || !accessKey || !secret || !bucket ||
        !/^[a-f0-9]{32}$/i.test(account) ||
        !/^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$/i.test(bucket)) {
      throw new ServiceUnavailableException({
        code: 'SELLER_R2_NOT_CONFIGURED',
        message: 'Seller media storage is not configured.',
      });
    }
    return { account, accessKey, secret, bucket };
  }

  private encode(value: string): string {
    return encodeURIComponent(value).replace(/[!'()*]/g, ch =>
      '%' + ch.charCodeAt(0).toString(16).toUpperCase());
  }

  sign(key: string, method: 'PUT' | 'GET' | 'HEAD' | 'DELETE',
       expiresSeconds: number, mimeType?: string): string {
    if (!/^seller-listings\/[0-9a-f-]{36}\/[0-9a-f-]{36}\/[0-9a-f-]{36}\.(?:jpg|png|webp|pdf)$/.test(key)) {
      throw new Error('Invalid server-managed storage key');
    }
    if (expiresSeconds < 1 || expiresSeconds > 600) throw new Error('Invalid signature lifetime');
    const { account, accessKey, secret, bucket } = this.settings();
    const host = `${account}.r2.cloudflarestorage.com`;
    const path = '/' + [bucket, ...key.split('/')].map(segment => this.encode(segment)).join('/');
    const stamp = new Date().toISOString().replace(/[-:]|\.\d{3}/g, '');
    const date = stamp.slice(0, 8);
    const scope = `${date}/auto/s3/aws4_request`;
    const signedHeaders = mimeType ? 'content-type;host' : 'host';
    const headers = mimeType
      ? `content-type:${mimeType}\nhost:${host}\n`
      : `host:${host}\n`;
    const values: Record<string, string> = {
      'X-Amz-Algorithm': 'AWS4-HMAC-SHA256',
      'X-Amz-Content-Sha256': 'UNSIGNED-PAYLOAD',
      'X-Amz-Credential': `${accessKey}/${scope}`,
      'X-Amz-Date': stamp,
      'X-Amz-Expires': String(expiresSeconds),
      'X-Amz-SignedHeaders': signedHeaders,
    };
    const query = Object.entries(values).sort(([a], [b]) => a.localeCompare(b))
      .map(([k, v]) => `${this.encode(k)}=${this.encode(v)}`).join('&');
    const canonical = [method, path, query, headers, signedHeaders, 'UNSIGNED-PAYLOAD'].join('\n');
    const digest = createHash('sha256').update(canonical).digest('hex');
    const stringToSign = ['AWS4-HMAC-SHA256', stamp, scope, digest].join('\n');
    const hmac = (key: Buffer | string, data: string): Buffer =>
      createHmac('sha256', key).update(data).digest();
    const signingKey = hmac(hmac(hmac(hmac('AWS4' + secret, date), 'auto'), 's3'), 'aws4_request');
    const signature = createHmac('sha256', signingKey).update(stringToSign).digest('hex');
    return `https://${host}${path}?${query}&X-Amz-Signature=${signature}`;
  }

  async verifyUploaded(key: string, mimeType: string, expectedSize: number): Promise<void> {
    const head = await fetch(this.sign(key, 'HEAD', 60), { method: 'HEAD', redirect: 'error', signal: AbortSignal.timeout(10_000) });
    if (head.status === 403) {
      this.logger.error('Cloudflare R2 denied HEAD verification; check bucket-scoped token permissions.');
      throw new ServiceUnavailableException({
        code: 'SELLER_R2_ACCESS_DENIED',
        message: 'Cloudflare R2 rejected media verification. Check the API storage credentials and bucket permissions.',
      });
    }
    if (head.status >= 500) {
      throw new ServiceUnavailableException({
        code: 'SELLER_R2_VERIFICATION_UNAVAILABLE',
        message: 'Cloudflare R2 is temporarily unavailable for media verification.',
      });
    }
    if (!head.ok || head.headers.get('content-type')?.split(';')[0]?.trim() !== mimeType ||
        Number(head.headers.get('content-length')) !== expectedSize) {
      throw new Error('R2 object metadata does not match the requested file.');
    }

    // Verify actual bytes rather than trusting a browser-provided MIME label.
    const response = await fetch(this.sign(key, 'GET', 60), {
      headers: { Range: 'bytes=0-31' }, redirect: 'error', signal: AbortSignal.timeout(10_000),
    });
    if (response.status === 403) {
      throw new ServiceUnavailableException({
        code: 'SELLER_R2_ACCESS_DENIED',
        message: 'Cloudflare R2 rejected verified-file access. Check the bucket token and permissions.',
      });
    }
    if (response.status >= 500) {
      throw new ServiceUnavailableException({
        code: 'SELLER_R2_VERIFICATION_UNAVAILABLE',
        message: 'Cloudflare R2 is temporarily unavailable for media verification.',
      });
    }
    if (response.status !== 206) throw new Error('R2 did not honor bounded signature inspection.');
    const signature = new Uint8Array(await response.arrayBuffer());
    const looksLike = mimeType === 'image/png'
      ? [137,80,78,71,13,10,26,10].every((value, i) => signature[i] === value)
      : mimeType === 'image/jpeg'
      ? signature[0] === 255 && signature[1] === 216 && signature[2] === 255
      : mimeType === 'image/webp'
      ? String.fromCharCode(...signature.slice(0,4)) === 'RIFF' &&
        String.fromCharCode(...signature.slice(8,12)) === 'WEBP'
      : mimeType === 'application/pdf'
      ? String.fromCharCode(...signature.slice(0,5)) === '%PDF-'
      : false;
    if (!looksLike) throw new Error('File contents do not match the declared type.');
    if (mimeType === 'image/webp') {
      if (signature.length < 12 ||
          new DataView(signature.buffer, signature.byteOffset + 4, 4).getUint32(0, true) !== expectedSize - 8) {
        throw new Error('WebP RIFF length does not match the object.');
      }
    }
    const tailStart = Math.max(0, expectedSize - 128);
    const tailResponse = await fetch(this.sign(key, 'GET', 60), {
      headers: { Range: `bytes=${tailStart}-${expectedSize - 1}` }, redirect: 'error', signal: AbortSignal.timeout(10_000),
    });
    if (tailResponse.status !== 206) throw new Error('R2 did not return bounded object footer.');
    const tail = new Uint8Array(await tailResponse.arrayBuffer());
    const last = tail.length - 1;
    const footerValid = mimeType === 'image/jpeg'
      ? last >= 1 && tail[last - 1] === 255 && tail[last] === 217
      : mimeType === 'image/png'
      ? tail.length >= 12 &&
        Buffer.from(tail.slice(-12)).toString('hex') === '0000000049454e44ae426082'
      : mimeType === 'application/pdf'
      ? new TextDecoder('latin1').decode(tail).includes('%%EOF')
      : true;
    if (!footerValid) throw new Error('Uploaded file is truncated or has an invalid footer.');
  }

  /**
   * Seal an untrusted browser upload under a fresh key that has NEVER been the
   * target of a browser-visible PUT signature. Otherwise the browser could
   * overwrite reviewed content until its 5-minute PUT URL expires.
   */
  async sealUpload(uploadKey: string, mimeType: string, expectedSize: number): Promise<string> {
    const sealedKey = uploadKey.replace(/\/[0-9a-f-]{36}(\.(?:jpg|png|webp|pdf))$/i,
      (_part, extension: string) => `/${randomUUID()}${extension}`);
    if (sealedKey === uploadKey) throw new Error('Invalid temporary upload key.');
    const download = await fetch(this.sign(uploadKey, 'GET', 60), {
      redirect: 'error', signal: AbortSignal.timeout(20_000),
    });
    if (!download.ok || !download.body) {
      throw new ServiceUnavailableException('Could not seal uploaded Seller media.');
    }
    // Bound memory even if the browser overwrote the temporary R2 object after
    // its initial HEAD check or R2 does not provide a Content-Length header.
    const reader = download.body.getReader();
    const chunks: Uint8Array[] = [];
    let readSize = 0;
    try {
      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        readSize += value.byteLength;
        if (readSize > expectedSize) {
          await reader.cancel();
          throw new Error('Uploaded object exceeds its verified file size.');
        }
        chunks.push(value);
      }
    } finally {
      reader.releaseLock();
    }
    if (readSize !== expectedSize) throw new Error('Uploaded object changed size.');
    const bytes = new Uint8Array(expectedSize);
    let offset = 0;
    for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
    const response = await fetch(this.sign(sealedKey, 'PUT', 60, mimeType), {
      method: 'PUT', headers: { 'Content-Type': mimeType },
      body: bytes, redirect: 'error', signal: AbortSignal.timeout(20_000),
    });
    if (!response.ok) {
      if (response.status === 403) this.logger.error('Cloudflare R2 denied sealed media PUT; inspect private bucket permission scope.');
      throw new ServiceUnavailableException({
        code: response.status === 403 ? 'SELLER_R2_ACCESS_DENIED' : 'SELLER_R2_FINALIZATION_FAILED',
        message: 'Cloudflare R2 rejected finalizing the Seller Listing image.',
      });
    }
    try {
      await this.verifyUploaded(sealedKey, mimeType, expectedSize);
    } catch (error) {
      await this.remove(sealedKey).catch(() => this.logger.warn('R2 cleanup pending after failed media verification.'));
      throw error;
    }
    return sealedKey;
  }

  async remove(key: string): Promise<void> {
    const response = await fetch(this.sign(key, 'DELETE', 60), {
      method: 'DELETE', redirect: 'error', signal: AbortSignal.timeout(10_000),
    });
    if (!response.ok && response.status !== 404) {
      throw new ServiceUnavailableException('Could not delete the uploaded Seller file.');
    }
  }
}
